<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class PurchaseReturnItem extends Model { protected $fillable=['purchase_return_id','purchase_item_id','quantity','unit_cost','line_total']; protected $casts=['quantity'=>'decimal:3','unit_cost'=>'decimal:2','line_total'=>'decimal:2']; public function return(){return $this->belongsTo(PurchaseReturn::class,'purchase_return_id');} public function purchaseItem(){return $this->belongsTo(PurchaseItem::class);} }
